CREATE OR REPLACE FUNCTION ECAMS.SRSTOP_YN
(ISRID IN VARCHAR2)
RETURN VARCHAR2
IS
   VCNT INT := 0;
 --- 개발중인 프로그램유무
BEGIN
    select count(*) cnt
      into VCNT
      from CMR0020
     where CR_ISRID=ISRID
       AND CR_STATUS NOT IN ('9','C');
     IF VCNT > 0 THEN
        RETURN 'NO';
     ELSE
        RETURN 'OK';
     END IF;

end;